pub struct Token {
    pub raw: String,
    pub expires_at: u64,
}

impl Token {
    pub fn verify(raw: &str, now: u64) -> Result<Self, String> {
        if raw.is_empty() {
            return Err("empty".into());
        }

        let expires_at = match raw.rsplit_once(':') {
            Some((value, expiry)) if !value.is_empty() => expiry
                .parse::<u64>()
                .map_err(|_| "invalid expiration".to_string())?,
            _ => u64::MAX,
        };

        if now >= expires_at {
            return Err("expired".into());
        }

        Ok(Self {
            raw: raw.to_string(),
            expires_at,
        })
    }
}

